//! Shared value types used across the transport core, the MCP server and the GUI.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

/// Direction / category of a chunk in a session log.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Direction {
    /// Bytes received from the remote side.
    Rx,
    /// Bytes sent to the remote side.
    Tx,
    /// Informational message generated by the tool itself.
    Info,
    /// Error message generated by the tool itself.
    Error,
    /// Telnet / NVT negotiation traffic.
    Nvt,
}

impl Direction {
    pub fn as_str(self) -> &'static str {
        match self {
            Direction::Rx => "rx",
            Direction::Tx => "tx",
            Direction::Info => "info",
            Direction::Error => "error",
            Direction::Nvt => "nvt",
        }
    }
}

/// Kind of transport backing a session.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SessionKind {
    Serial,
    TcpClient,
    TcpServer,
    Udp,
}

impl SessionKind {
    pub fn as_str(self) -> &'static str {
        match self {
            SessionKind::Serial => "serial",
            SessionKind::TcpClient => "tcp_client",
            SessionKind::TcpServer => "tcp_server",
            SessionKind::Udp => "udp",
        }
    }

    pub fn prefix(self) -> &'static str {
        match self {
            SessionKind::Serial => "serial",
            SessionKind::TcpClient => "tcp",
            SessionKind::TcpServer => "server",
            SessionKind::Udp => "udp",
        }
    }
}

/// State of the RS-232 modem / handshake lines.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct ModemLines {
    /// Clear To Send (input).
    pub cts: bool,
    /// Data Set Ready (input).
    pub dsr: bool,
    /// Ring Indicator (input).
    pub ri: bool,
    /// Carrier Detect (input).
    pub cd: bool,
    /// Request To Send (output).
    pub rts: bool,
    /// Data Terminal Ready (output).
    pub dtr: bool,
}

/// A client currently attached to a TCP server session.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ClientInfo {
    pub id: u64,
    pub peer: String,
    pub connected_at: DateTime<Utc>,
}

/// Runtime control operations that can be applied to a live session.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ControlOp {
    Rts(bool),
    Dtr(bool),
    Break(bool),
    Echo(bool),
}

/// Events emitted by the session manager. The GUI and MCP transports can subscribe.
#[derive(Debug, Clone)]
pub enum SessionEvent {
    Opened {
        id: String,
        kind: SessionKind,
        label: String,
    },
    Data {
        id: String,
        dir: Direction,
        len: usize,
    },
    Connected {
        id: String,
        peer: Option<String>,
    },
    Disconnected {
        id: String,
        reason: String,
    },
    ClientsChanged {
        id: String,
        count: usize,
    },
    ModemChanged {
        id: String,
        lines: ModemLines,
    },
    Error {
        id: String,
        message: String,
    },
    Info {
        id: String,
        message: String,
    },
    Closed {
        id: String,
    },
}
